#!/usr/bin/env python3
import hashlib,json,os,subprocess
from pathlib import Path
r=Path(__file__).resolve().parent;t=Path(os.environ.get('DIFFUSION_TOOLCHAIN',str(r.parent/'toolchain'))).resolve();out=r/'build';out.mkdir(exist_ok=True)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
pin=json.loads((t/'provenance.json').read_text());compiler=t/'hikec';assert sha(compiler)==pin['sha256']['compiler']
env=dict(os.environ,PATH=str(t/'wabt/node_modules/.bin')+os.pathsep+os.environ['PATH'])
command=[str(compiler),'build','-target','wabt','-wasm-mode','normal','-o',str(out/'latent-space.wasm'),str(r/'latent-space.hike')]
p=subprocess.run(command,env=env,capture_output=True,text=True);(out/'compiler.log').write_text(p.stdout+p.stderr);p.check_returncode()
subprocess.run(['node',str(t/'wabt/node_modules/wabt/bin/wasm2wat'),str(out/'latent-space.wasm'),'-o',str(out/'latent-space.wat')],check=True)
wat=(out/'latent-space.wat').read_text();assert '(import ' not in wat
record={'hikeCommit':pin['hikeCommit'],'compilerSha256':sha(compiler),'sourceSha256':sha(r/'latent-space.hike'),'wasmSha256':sha(out/'latent-space.wasm'),'watSha256':sha(out/'latent-space.wat'),'generatedRuntimeSha256':sha(out/'runtime.js'),'runtimeUsed':False,'versions':pin['versions'],'backend':'wabt normal','command':command,'imports':[],'scope':'Wan21 raw posterior-mean fixedprofile normalization, no model inference'}
(out/'build-record.json').write_text(json.dumps(record,indent=2)+'\n')
(r/'kernel-registry.mjs').write_text('// Generated by build.py from real Hike output.\nexport const LATENT_SPACE_KERNEL=Object.freeze({abi:"wan21-raw-mean-f32-v1",sha256:"'+record['wasmSha256']+'",sourceSha256:"'+record['sourceSha256']+'",url:new URL("./build/latent-space.wasm",import.meta.url).href});\n')
print(json.dumps(record))
